# A small sign-up service that applies this module's habits.
import hashlib
import hmac
import re

ROLES = {"viewer": {"read"}, "editor": {"read", "write"}, "admin": {"read", "write", "delete"}}
PSEUDONYM_KEY = b"keep-this-key-in-a-secret-store"

def validate(form):
    errors = []
    if not re.fullmatch(r"[A-Za-z0-9_]{3,20}", form.get("username", "")):
        errors.append("username: 3-20 letters, digits or _")
    if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[a-z]{2,}", form.get("email", "")):
        errors.append("email: not a valid address")
    age = form.get("age", "")
    if not age.isdigit() or not 13 <= int(age) <= 120:
        errors.append("age: a whole number from 13 to 120")
    return errors

def store(form):
    # Data minimization: keep only what the app needs; pseudonymize the email for analytics.
    tag = hmac.new(PSEUDONYM_KEY, form["email"].lower().encode(), hashlib.sha256).hexdigest()[:12]
    return {"username": form["username"], "role": "viewer", "email_id": tag}

def allowed(user, action):
    return action in ROLES[user["role"]]

for form in [{"username": "ana_r", "email": "ana@example.com", "age": "16", "phone": "555-0101"},
             {"username": "x", "email": "not-an-email", "age": "200"}]:
    errors = validate(form)
    if errors:
        print("rejected:", errors)
        continue
    user = store(form)
    print("stored:", user)
    print("can read:", allowed(user, "read"), "| can delete:", allowed(user, "delete"))

