import re

def valid_username(name):
    return re.fullmatch(r"[A-Za-z0-9_]{3,20}", name) is not None

def is_vulnerable(installed, fixed_in):
    parse = lambda v: tuple(int(p) for p in v.split("."))
    return parse(installed) < parse(fixed_in)

def mask_email(email):
    name, domain = email.split("@", 1)
    return name[0] + "*" * (len(name) - 1) + "@" + domain
